c5=A.au(s2,A.a([A.at(A.a(["\ubbf8\uc801\ubd84\u2160 > \uc18d\ub3c4\uc640\uac00\uc18d\ub3c4 > \uac00\uc18d\ub3c4 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.av(s3,B.q,A.a(["\uac00\uc18d\ub3c4\ub780 \ubb3c\uccb4\uc758 \uc18d\ub3c4\uac00 \uc2dc\uac04\uc5d0 \ub530\ub77c \uc5bc\ub9c8\ub098 \ube60\ub974\uac8c \ubcc0\ud558\ub294\uc9c0\ub97c \ub098\ud0c0\ub0b4\ub294 \ubb3c\ub9ac\ub7c9\uc785\ub2c8\ub2e4. \uc218\uc9c1\uc120 \uc704\ub97c \uc6c0\uc9c1\uc774\ub294 \uc810 $P$\uc758 \uc2dc\uac01 $t$\uc5d0\uc11c\uc758 \uc704\uce58\ub97c $x(t)$\ub77c\uace0 \ud560 \ub54c, \uc18d\ub3c4 $v(t)$\ub294 \uc704\uce58\ub97c \uc2dc\uac04\uc5d0 \ub300\ud574 \ubbf8\ubd84\ud558\uc5ec $v(t) = \\frac{dx}{dt} = x'(t)$\ub85c \uc815\uc758\ud569\ub2c8\ub2e4. \uc774\ub54c \uac00\uc18d\ub3c4 $a(t)$\ub294 \uc18d\ub3c4\ub97c \ub2e4\uc2dc \uc2dc\uac04\uc5d0 \ub300\ud574 \ud55c \ubc88 \ub354 \ubbf8\ubd84\ud55c \uac12\uc73c\ub85c, \ub2e4\uc74c\uacfc \uac19\uc774 \uc815\uc758\ub429\ub2c8\ub2e4. $$a(t) = \\frac{dv}{dt} = v'(t) = x''(t)$$","\uac00\uc18d\ub3c4\uc758 \ubd80\ud638\ub294 \uc18d\ub3c4\uc758 \ubcc0\ud654 \ubc29\ud5a5\uc744 \uacb0\uc815\ud569\ub2c8\ub2e4. \uac00\uc18d\ub3c4\uac00 \uc591\uc218($a(t) > 0$)\uc774\uba74 \uc18d\ub3c4\uac00 \uc99d\uac00\ud558\ub294 \ubc29\ud5a5\uc73c\ub85c \ud798\uc774 \uc791\uc6a9\ud558\uace0 \uc788\uc74c\uc744 \uc758\ubbf8\ud558\uba70, \uac00\uc18d\ub3c4\uac00 \uc74c\uc218($a(t) < 0$)\uc774\uba74 \uc18d\ub3c4\uac00 \uac10\uc18c\ud558\ub294 \ubc29\ud5a5\uc73c\ub85c \ud798\uc774 \uc791\uc6a9\ud568\uc744 \ub73b\ud569\ub2c8\ub2e4. \ud2b9\ud788 \uac00\uc18d\ub3c4\uac00 $0$\uc778 \uc21c\uac04\uc740 \ubb3c\uccb4\uc758 \uc18d\ub3c4\uac00 \uc77c\uc2dc\uc801\uc73c\ub85c \ubcc0\ud558\uc9c0 \uc54a\ub294 \uc0c1\ud0dc\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uc18d\ub3c4\uc640 \uac00\uc18d\ub3c4\uc758 \ubd80\ud638\uac00 \uac19\uc73c\uba74 \ubb3c\uccb4\uc758 \uc18d\ub825\uc740 \uc810\uc810 \ube68\ub77c\uc9c0\uace0, \ub450 \uac12\uc758 \ubd80\ud638\uac00 \ub2e4\ub974\uba74 \ubb3c\uccb4\uc758 \uc18d\ub825\uc740 \uc810\uc810 \ub290\ub824\uc9c0\uac8c \ub429\ub2c8\ub2e4.","\uc608\ub97c \ub4e4\uc5b4, \uc218\uc9c1\uc120 \uc704\ub97c \uc6c0\uc9c1\uc774\ub294 \uc810 $P$\uc758 \uc2dc\uac01 $t$\uc5d0\uc11c\uc758 \uc704\uce58\uac00 $x(t) = t^3 - 6t^2 + 9t$\ub85c \uc8fc\uc5b4\uc84c\ub2e4\uace0 \uac00\uc815\ud574 \ubd05\uc2dc\ub2e4. \uc774\ub54c \uc2dc\uac01 $t=3$\uc5d0\uc11c\uc758 \uac00\uc18d\ub3c4\ub97c \uad6c\ud558\ub294 \uacfc\uc815\uc744 \ub2e8\uacc4\ubcc4\ub85c \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uc18d\ub3c4 $v(t)$\ub97c \uad6c\ud558\uae30 \uc704\ud574 \uc704\uce58 \ud568\uc218 $x(t)$\ub97c $t$\uc5d0 \ub300\ud558\uc5ec \ubbf8\ubd84\ud569\ub2c8\ub2e4. $$v(t) = \\frac{dx}{dt} = 3t^2 - 12t + 9$$","\ub2e4\uc74c\uc73c\ub85c, \uad6c\ud55c \uc18d\ub3c4 \ud568\uc218 $v(t)$\ub97c \ud55c \ubc88 \ub354 $t$\uc5d0 \ub300\ud558\uc5ec \ubbf8\ubd84\ud558\uc5ec \uac00\uc18d\ub3c4 \ud568\uc218 $a(t)$\ub97c \uad6c\ud569\ub2c8\ub2e4. $$a(t) = \\frac{dv}{dt} = 6t - 12$$ \uc774\uc81c \ubb38\uc81c\uc5d0\uc11c \uc694\uad6c\ud55c \uc2dc\uac01 $t=3$\uc744 \uac00\uc18d\ub3c4 \ud568\uc218\uc5d0 \ub300\uc785\ud569\ub2c8\ub2e4. $$a(3) = 6(3) - 12 = 18 - 12 = 6$$ \ub530\ub77c\uc11c \uc2dc\uac01 $t=3$\uc5d0\uc11c\uc758 \uc810 $P$\uc758 \uac00\uc18d\ub3c4\ub294 $6$\uc785\ub2c8\ub2e4."],ai0),"\uac00\uc18d\ub3c4",B.p)],ai2),"\uac00\uc18d\ub3c4",B.p)],ai3),s3,s3,s3,"concept_\uac00\uc18d\ub3c4",0,"","\ubbf8\uc801\ubd84\u2160 > \uc18d\ub3c4\uc640\uac00\uc18d\ub3c4 > \uac00\uc18d\ub3c4",c5,"\uac00\uc18d\ub3c4",s3)
c6=A.a(["\uacf5\ud1b5\uc218\ud5592","\ud568\uc218","\ud569\uc131\ud568\uc218","\ud569\uc131\ud568\uc218\uc758\uc815\uc758"],ai0)
c6=A.au(s2,A.a([A.at(A.a(["\uacf5\ud1b5\uc218\ud5592 > \ud568\uc218 > \ud569\uc131\ud568\uc218 > \ud569\uc131\ud568\uc218\uc758\uc815\uc758 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.av(s3,B.q,A.a(["\ud569\uc131\ud568\uc218\ub780 \ub450 \ud568\uc218\ub97c \uc774\uc5b4 \ubd99\uc5ec \ud558\ub098\uc758 \uc0c8\ub85c\uc6b4 \ud568\uc218\ub97c \ub9cc\ub4dc\ub294 \uacfc\uc815\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \ub450 \uc9d1\ud569 $X, Y, Z$\uc5d0 \ub300\ud558\uc5ec \ud568\uc218 $f: X \\to Y$\uc640 \ud568\uc218 $g: Y \\to Z$\uac00 \uc788\uc744 \ub54c, \uc9d1\ud569 $X$\uc758 \uc784\uc758\uc758 \uc6d0\uc18c $x$\ub97c $f$\uc5d0 \uc758\ud574 $f(x)$\ub85c \ubcf4\ub0b4\uace0, \ub2e4\uc2dc \uadf8 \uacb0\uacfc\uac12\uc778 $f(x)$\ub97c $g$\uc5d0 \uc758\ud574 $g(f(x))$\ub85c \ubcf4\ub0b4\ub294 \ub300\uc751\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub54c \uc9d1\ud569 $X$\uc758 \uac01 \uc6d0\uc18c $x$\ub97c $g(f(x))$\uc5d0 \ub300\uc751\uc2dc\ud0a4\ub294 \uc0c8\ub85c\uc6b4 \ud568\uc218\ub97c $f$\uc640 $g$\uc758 \ud569\uc131\ud568\uc218\ub77c\uace0 \ud558\uba70, \uae30\ud638\ub85c\ub294 $g \\circ f$\uc640 \uac19\uc774 \ub098\ud0c0\ub0c5\ub2c8\ub2e4.","\ud569\uc131\ud568\uc218 $(g \\circ f)(x)$\uc758 \uc815\uc758\ub97c \uc218\uc2dd\uc73c\ub85c \ud45c\ud604\ud558\uba74 $$(g \\circ f)(x) = g(f(x))$$\uac00 \ub429\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uc810\uc740 \ud569\uc131\ud568\uc218\uac00 \uc815\uc758\ub418\uae30 \uc704\ud574\uc11c\ub294 \uccab \ubc88\uc9f8 \ud568\uc218 $f$\uc758 \uacf5\uc5ed\uc774 \ub450 \ubc88\uc9f8 \ud568\uc218 $g$\uc758 \uc815\uc758\uc5ed\uc758 \ubd80\ubd84\uc9d1\ud569\uc774\uc5b4\uc57c \ud55c\ub2e4\ub294 \uac83\uc785\ub2c8\ub2e4. \ub610\ud55c, \ud569\uc131\ud568\uc218\ub294 \uc77c\ubc18\uc801\uc73c\ub85c \uad50\ud658\ubc95\uce59\uc774 \uc131\ub9bd\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc989, $f \\circ g$\uc640 $g \\circ f$\ub294 \uc11c\ub85c \ub2e4\ub978 \ud568\uc218\uc778 \uacbd\uc6b0\uac00 \ub9ce\uc73c\ubbc0\ub85c \uc21c\uc11c\uc5d0 \uc8fc\uc758\ud558\uc5ec \uacc4\uc0b0\ud574\uc57c \ud569\ub2c8\ub2e4.","\ud569\uc131\ud568\uc218\uc758 \uc131\uc9c8 \uc911 \uac00\uc7a5 \ub300\ud45c\uc801\uc778 \uac83\uc740 \uacb0\ud569\ubc95\uce59\uc785\ub2c8\ub2e4. \uc138 \ud568\uc218 $f, g, h$\uc5d0 \ub300\ud558\uc5ec $(h \\circ g) \\circ f = h \\circ (g \\circ f)$\uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4. \uc774\ub294 \ud568\uc218\ub97c \ud569\uc131\ud558\ub294 \uc21c\uc11c\uac00 \uac19\uae30\ub9cc \ud558\ub2e4\uba74, \uc5b4\ub290 \ucabd\uc744 \uba3c\uc800 \ud569\uc131\ud558\ub354\ub77c\ub3c4 \uacb0\uacfc\uac00 \uac19\uc74c\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc131\uc9c8 \ub355\ubd84\uc5d0 \uc6b0\ub9ac\ub294 \uc138 \uac1c \uc774\uc0c1\uc758 \ud568\uc218\ub97c \ud569\uc131\ud560 \ub54c \uad04\ud638\ub97c \uc0dd\ub7b5\ud558\uace0 $h \\circ g \\circ f$\uc640 \uac19\uc774 \uac04\ub2e8\ud788 \ud45c\uae30\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \ud569\uc131\ud568\uc218\ub97c \uacc4\uc0b0\ud574 \ubd05\uc2dc\ub2e4. \ub450 \ud568\uc218 $f(x) = 2x + 1$\uacfc $g(x) = x^2$\uc774 \uc8fc\uc5b4\uc84c\uc744 \ub54c, $(g \\circ f)(2)$\uc758 \uac12\uc744 \uad6c\ud558\ub294 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. \uba3c\uc800 \ud569\uc131\ud568\uc218\uc758 \uc815\uc758\uc5d0 \ub530\ub77c $(g \\circ f)(2) = g(f(2))$\ub85c \uc2dd\uc744 \ubcc0\ud615\ud569\ub2c8\ub2e4. \ub2e8\uacc4\ubcc4\ub85c \uacc4\uc0b0\ud558\uba74, \uba3c\uc800 $f(2)$\uc758 \uac12\uc744 \uad6c\ud569\ub2c8\ub2e4. $f(2) = 2(2) + 1 = 5$\uc785\ub2c8\ub2e4. \uc774\uc81c \uc774 \uacb0\uacfc\uac12\uc744 $g$\uc5d0 \ub300\uc785\ud558\uba74 $g(5) = 5^2 = 25$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c $(g \\circ f)(2) = 25$\uc785\ub2c8\ub2e4.","\uc774\ubc88\uc5d0\ub294 \ud568\uc218\uc2dd \uc790\uccb4\ub97c \ud569\uc131\ud558\ub294 \uc5f0\uc2b5\uc744 \ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. $f(x) = x - 3$\uc774\uace0 $g(x) = 3x + 2$\uc77c \ub54c, $(f \\circ g)(x)$\ub97c \uad6c\ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc815\uc758\uc5d0 \uc758\ud574 $(f \\circ g)(x) = f(g(x))$\uc785\ub2c8\ub2e4. \uc5ec\uae30\uc11c $g(x)$ \uc790\ub9ac\uc5d0 $3x + 2$\ub97c \ub300\uc785\ud558\uba74 $f(3x + 2)$\uac00 \ub429\ub2c8\ub2e4. \uc774\uc81c $f$\uc758 \uc815\uc758\uc5d0 \ub530\ub77c $x$ \ub300\uc2e0 $(3x + 2)$\ub97c \ub123\uc73c\uba74 $f(3x + 2) = (3x + 2) - 3$\uc774 \ub429\ub2c8\ub2e4. \uc774\ub97c \uc815\ub9ac\ud558\uba74 \ucd5c\uc885\uc801\uc73c\ub85c $$(f \\circ g)(x) = 3x - 1$$\uc774\ub77c\ub294 \uacb0\uacfc\ub97c \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),v7,B.p)],ai2),v7,B.p)],ai3),s3,s3,s3,"concept_\ud569\uc131\ud568\uc218\uc758\uc815\uc758",0,"","\uacf5\ud1b5\uc218\ud5592 > \ud568\uc218 > \ud569\uc131\ud568\uc218 > \ud569\uc131\ud568\uc218\uc758\uc815\uc758",c6,v7,s3)
c7=A.a(["\uacf5\ud1b5\uc218\ud5591","\uacbd\uc6b0\uc758\uc218","\uc21c\uc5f4","\uc6d0\uc21c\uc5f4"],ai0)
c7=A.au(s2,A.a([A.at(A.a(["\uacf5\ud1b5\uc218\ud5591 > \uacbd\uc6b0\uc758\uc218 > \uc21c\uc5f4 > \uc6d0\uc21c\uc5f4 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.av(s3,B.q,A.a(["\uc6d0\uc21c\uc5f4\uc774\ub780 \uc11c\ub85c \ub2e4\ub978 $n$\uac1c\ub97c \uc6d0\ud615\uc73c\ub85c \ubc30\uc5f4\ud558\ub294 \uacbd\uc6b0\uc758 \uc218\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc77c\ubc18\uc801\uc778 \uc21c\uc5f4\uc740 \uc77c\ub82c\ub85c \ub098\uc5f4\ud558\uae30 \ub54c\ubb38\uc5d0 \uc2dc\uc791\uacfc \ub05d\uc774 \ubd84\uba85\ud558\uc9c0\ub9cc, \uc6d0\ud615\uc73c\ub85c \ubc30\uc5f4\ud560 \ub54c\ub294 \ud68c\uc804\ud558\uc5ec \uc77c\uce58\ud558\ub294 \uacbd\uc6b0\ub97c \ubaa8\ub450 \uac19\uc740 \uac83\uc73c\ub85c \uac04\uc8fc\ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, 4\uba85\uc744 \uc6d0\ud0c1\uc5d0 \uc549\ud790 \ub54c \uc77c\ub82c\ub85c \ub098\uc5f4\ud558\uba74 $4!$\uac00\uc9c0\uc774\uc9c0\ub9cc, \uc6d0\ud0c1\uc5d0\uc11c\ub294 \ud68c\uc804\ud588\uc744 \ub54c \uacb9\uce58\ub294 4\uac00\uc9c0 \uacbd\uc6b0\ub97c \ud558\ub098\ub85c \ubcf4\uc544\uc57c \ud569\ub2c8\ub2e4.","\ub530\ub77c\uc11c \uc6d0\uc21c\uc5f4\uc758 \ud575\uc2ec\uc740 '\ud68c\uc804\uc758 \uc911\ubcf5\uc744 \uc81c\uac70\ud558\ub294 \uac83'\uc785\ub2c8\ub2e4. $n$\uac1c\ub97c \uc6d0\ud615\uc73c\ub85c \ubc30\uc5f4\ud558\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 \uc77c\ub82c\ub85c \ub098\uc5f4\ud558\ub294 \uc218\uc778 $n!$\uc744 \ud68c\uc804\ud588\uc744 \ub54c \uac19\uc740 \ubaa8\uc591\uc774 \ub418\ub294 \uac1c\uc218\uc778 $n$\uc73c\ub85c \ub098\ub204\uc5b4 \uacc4\uc0b0\ud569\ub2c8\ub2e4. \uc774\ub97c \uacf5\uc2dd\uc73c\ub85c \ub098\ud0c0\ub0b4\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$ \\frac{n!}{n} = (n-1)! $$ \uc774 \uacf5\uc2dd\uc740 \ud55c \uba85\uc744 \uace0\uc815\ud558\uace0 \ub098\uba38\uc9c0 $(n-1)$\uba85\uc744 \uc77c\ub82c\ub85c \ub098\uc5f4\ud558\ub294 \uac83\uacfc \uac19\uc740 \uc6d0\ub9ac\ub85c \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc6d0\uc21c\uc5f4\uc758 \uc131\uc9c8\uc744 \ud655\uc7a5\ud558\uba74, $n$\uac1c\uc758 \uc790\ub9ac\uac00 \ubaa8\ub450 \uad6c\ubcc4\ub418\uc9c0 \uc54a\uc744 \ub54c \ud2b9\uc815 \ub300\uc0c1\uc744 \uace0\uc815\ud558\ub294 \ubc29\uc2dd\uc774 \ub9e4\uc6b0 \uc720\uc6a9\ud569\ub2c8\ub2e4. \ub9cc\uc57d $n$\uac1c\uc758 \uc790\ub9ac\uac00 \ubc88\ud638\uac00 \ub9e4\uaca8\uc838 \uc788\uac70\ub098 \uc704\uce58\uac00 \uad6c\ubcc4\ub41c\ub2e4\uba74 \uc77c\ubc18 \uc21c\uc5f4\uc744 \uc0ac\uc6a9\ud574\uc57c \ud558\uc9c0\ub9cc, \ub2e8\uc21c\ud788 \uc6d0\ud0c1\uc5d0 \ub458\ub7ec\uc549\ub294 \uc0c1\ud669\uc774\ub77c\uba74 \uc704 \uacf5\uc2dd\uc744 \uc801\uc6a9\ud569\ub2c8\ub2e4. \ub610\ud55c, \uc6d0\uc21c\uc5f4\uc740 \ub2e4\uac01\ud615\uc758 \ud0c1\uc790\uc5d0 \uc549\uac70\ub098 \ubaa9\uac78\uc774\ub97c \ub9cc\ub4dc\ub294 \ub4f1 \ub300\uce6d\uc131\uc744 \uace0\ub824\ud574\uc57c \ud558\ub294 \ubb38\uc81c\ub85c \uc751\uc6a9\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc608\uc81c: 5\uba85\uc758 \ud559\uc0dd\uc774 \uc6d0\ud615 \ud0c1\uc790\uc5d0 \ub458\ub7ec\uc549\ub294 \uacbd\uc6b0\uc758 \uc218\ub97c \uad6c\ud558\uc2dc\uc624. \ub2e8\uacc4\ubcc4 \ud480\uc774: \uccab\uc9f8, \uc6d0\uc21c\uc5f4 \uacf5\uc2dd $(n-1)!$\uc744 \ub5a0\uc62c\ub9bd\ub2c8\ub2e4. \ub458\uc9f8, $n=5$\ub97c \uacf5\uc2dd\uc5d0 \ub300\uc785\ud569\ub2c8\ub2e4. \uc14b\uc9f8, \uacc4\uc0b0\uc744 \uc218\ud589\ud569\ub2c8\ub2e4. $$ (5-1)! = 4! = 4 \\times 3 \\times 2 \\times 1 = 24 $$ \ub530\ub77c\uc11c 5\uba85\uc758 \ud559\uc0dd\uc774 \uc6d0\ud615 \ud0c1\uc790\uc5d0 \uc549\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 24\uac00\uc9c0\uc785\ub2c8\ub2e4.","\uc2ec\ud654 \uc608\uc81c: \ub0a8\ud559\uc0dd 3\uba85\uacfc \uc5ec\ud559\uc0dd 2\uba85\uc774 \uc6d0\ud615 \ud0c1\uc790\uc5d0 \uc549\uc744 \ub54c, \uc5ec\ud559\uc0dd 2\uba85\uc774 \uc11c\ub85c \uc774\uc6c3\ud558\uac8c \uc549\ub294 \uacbd\uc6b0\uc758 \uc218\ub97c \uad6c\ud558\uc2dc\uc624. \ub2e8\uacc4\ubcc4 \ud480\uc774: \uccab\uc9f8, \uc774\uc6c3\ud558\ub294 \uc5ec\ud559\uc0dd 2\uba85\uc744 \ud55c \ubb36\uc74c\uc73c\ub85c \uc0dd\uac01\ud569\ub2c8\ub2e4. \ub458\uc9f8, \uc804\uccb4 4\uac1c\uc758 \ubb36\uc74c(\ub0a8\ud559\uc0dd 3\uba85 + \uc5ec\ud559\uc0dd \ubb36\uc74c 1\uac1c)\uc744 \uc6d0\ud615\uc73c\ub85c \ubc30\uc5f4\ud558\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 $(4-1)! = 3! = 6$\uc785\ub2c8\ub2e4. \uc14b\uc9f8, \ubb36\uc74c \uc548\uc5d0\uc11c \uc5ec\ud559\uc0dd 2\uba85\uc774 \uc790\ub9ac\ub97c \ubc14\uafb8\ub294 \uacbd\uc6b0\uc758 \uc218 $2! = 2$\ub97c \uacf1\ud569\ub2c8\ub2e4. $$ 3! \\times 2! = 6 \\times 2 = 12 $$ \ub530\ub77c\uc11c \uad6c\ud558\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 12\uac00\uc9c0\uc785\ub2c8\ub2e4."],ai0),"\uc6d0\uc21c\uc5f4",B.p)],ai2),"\uc6d0\uc21c\uc5f4",B.p)],ai3),s3,s3,s3,"concept_\uc6d0\uc21c\uc5f4",0,"","\uacf5\ud1b5\uc218\ud5591 > \uacbd\uc6b0\uc758\uc218 > \uc21c\uc5f4 > \uc6d0\uc21c\uc5f4",c7,"\uc6d0\uc21c\uc5f4",s3)
c8=A.a(["\ubbf8\uc801\ubd84\u2160","\ud568\uc218\uc758\uadf9\ud55c","\uadf9\ud55c\uc758\uc131\uc9c8","\uadf9\ud55c\uc758\uc0ac\uce59\uc5f0\uc0b0"],ai0)
c8=A.au(s2,A.a([A.at(A.a(["\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uadf9\ud55c > \uadf9\ud55c\uc758\uc131\uc9c8 > \uadf9\ud55c\uc758\uc0ac\uce59\uc5f0\uc0b0 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.av(s3,B.q,A.a(["\ud568\uc218\uc758 \uadf9\ud55c\uc5d0\uc11c \uac00\uc7a5 \uae30\ubcf8\uc774 \ub418\ub294 \uc131\uc9c8\uc740 \ub450 \ud568\uc218\uc758 \uadf9\ud55c\uac12\uc774 \uc874\uc7ac\ud560 \ub54c, \uc0ac\uce59\uc5f0\uc0b0\uc5d0 \ub300\ud558\uc5ec \uadf9\ud55c \uae30\ud638\ub97c \uc790\uc720\ub86d\uac8c \ubd84\ubc30\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. \ub450 \ud568\uc218 $f(x)$\uc640 $g(x)$\uc5d0 \ub300\ud558\uc5ec $x$\uac00 $a$\ub85c \ud55c\uc5c6\uc774 \uac00\uae4c\uc6cc\uc9c8 \ub54c, $\\lim_{x \\to a} f(x) = \\alpha$, $\\lim_{x \\to a} g(x) = \\beta$ (\ub2e8, $\\alpha, \\beta$\ub294 \uc2e4\uc218)\ub77c\uace0 \uac00\uc815\ud569\uc2dc\ub2e4. \uc774\ub54c \ub450 \ud568\uc218\uc758 \ud569, \ucc28, \uacf1, \uadf8\ub9ac\uace0 \ub098\ub217\uc148\uc5d0 \ub300\ud55c \uadf9\ud55c\uc740 \uac01\uac01\uc758 \uadf9\ud55c\uac12\uc744 \uba3c\uc800 \uad6c\ud55c \ub4a4 \uc0ac\uce59\uc5f0\uc0b0\uc744 \uc218\ud589\ud55c \uacb0\uacfc\uc640 \uac19\uc2b5\ub2c8\ub2e4.","\uc774\ub97c \uc218\ud559\uc801 \uacf5\uc2dd\uc73c\ub85c \ub098\ud0c0\ub0b4\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \ub367\uc148\uacfc \ube84\uc148\uc740 $\\lim_{x \\to a} \\{f(x) \\pm g(x)\\} = \\lim_{x \\to a} f(x) \\pm \\lim_{x \\to a} g(x) = \\alpha \\pm \\beta$\uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4. \uacf1\uc148\uc758 \uacbd\uc6b0 $\\lim_{x \\to a} \\{f(x)g(x)\\} = \\lim_{x \\to a} f(x) \\cdot \\lim_{x \\to a} g(x) = \\alpha \\cdot \\beta$\uc774\uba70, \uc0c1\uc218 $c$\uac00 \uacf1\ud574\uc9c4 \uacbd\uc6b0 $\\lim_{x \\to a} \\{c f(x)\\} = c \\cdot \\lim_{x \\to a} f(x) = c\\alpha$\uac00 \ub429\ub2c8\ub2e4.","\ub098\ub217\uc148\uc758 \uacbd\uc6b0\uc5d0\ub294 \ubd84\ubaa8\uac00 0\uc774 \ub418\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4\ub294 \uc911\uc694\ud55c \uc870\uac74\uc774 \ubd99\uc2b5\ub2c8\ub2e4. \uc989, $\\lim_{x \\to a} \\frac{f(x)}{g(x)} = \\frac{\\lim_{x \\to a} f(x)}{\\lim_{x \\to a} g(x)} = \\frac{\\alpha}{\\beta}$\uac00 \uc131\ub9bd\ud558\uba70, \uc774\ub54c \ubc18\ub4dc\uc2dc $\\beta \\neq 0$\uc774\uc5b4\uc57c \ud569\ub2c8\ub2e4. \uc774 \uc131\uc9c8\ub4e4\uc740 \uadf9\ud55c\uac12\uc774 \uc874\uc7ac\ud558\ub294 \uacbd\uc6b0\uc5d0\ub9cc \uc801\uc6a9\ud560 \uc218 \uc788\uc73c\ubbc0\ub85c, \ubb38\uc81c\ub97c \ud480 \ub54c \uac01 \ud568\uc218\uc758 \uadf9\ud55c\uac12\uc774 \uc2e4\uc81c\ub85c \uc874\uc7ac\ud558\ub294\uc9c0 \uba3c\uc800 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc744 \ub4e4\uc774\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc774\uc81c \uc608\uc81c\ub97c \ud1b5\ud574 \uc9c1\uc811 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. $\\lim_{x \\to 2} f(x) = 3$\uc774\uace0 $\\lim_{x \\to 2} g(x) = 4$\uc77c \ub54c, $\\lim_{x \\to 2} \\{2f(x) + g(x)\\}$\uc758 \uac12\uc744 \uad6c\ud558\ub294 \ubb38\uc81c\uc785\ub2c8\ub2e4. \uc774 \ubb38\uc81c\ub294 \uadf9\ud55c\uc758 \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uc5ec \uac01 \ud56d\uc73c\ub85c \ubd84\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub2e8\uacc4\ubcc4\ub85c \ud480\uc774\ud558\uba74, \uba3c\uc800 $\\lim_{x \\to 2} \\{2f(x) + g(x)\\} = 2\\lim_{x \\to 2} f(x) + \\lim_{x \\to 2} g(x)$\ub85c \uc2dd\uc744 \ub098\ub215\ub2c8\ub2e4.","\uc774\uc81c \uc8fc\uc5b4\uc9c4 \uadf9\ud55c\uac12\uc744 \ub300\uc785\ud569\ub2c8\ub2e4. $2 \\times 3 + 4$\ub97c \uacc4\uc0b0\ud558\uba74 $6 + 4 = 10$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uad6c\ud558\uace0\uc790 \ud558\ub294 \uadf9\ud55c\uac12\uc740 $10$\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uadf9\ud55c\uc758 \uc0ac\uce59\uc5f0\uc0b0 \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud55c \ud568\uc218\uc758 \uadf9\ud55c\ub3c4 \uac01\uac01\uc758 \ub2e8\uc21c\ud55c \uadf9\ud55c\uac12\ub4e4\uc758 \uc870\ud569\uc73c\ub85c \ubc14\uafb8\uc5b4 \uc27d\uac8c \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),v8,B.p)],ai2),v8,B.p)],ai3),s3,s3,s3,"concept_\uadf9\ud55c\uc758\uc0ac\uce59\uc5f0\uc0b0",0,"","\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uadf9\ud55c > \uadf9\ud55c\uc758\uc131\uc9c8 > \uadf9\ud55c\uc758\uc0ac\uce59\uc5f0\uc0b0",c8,v8,s3)
c9=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc6d0\uc758\ubc29\uc815\uc2dd","\uc6d0\uc758\ud45c\uc900\ud615","\ubc18\uc9c0\ub984"],ai0)
c9=A.au(s2,A.a([A.at(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc6d0\uc758\ubc29\uc815\uc2dd > \uc6d0\uc758\ud45c\uc900\ud615 > \ubc18\uc9c0\ub984 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.av(s3,B.q,A.a(['[   "\uc6d0\uc758 \uc815\uc758\ub294 \ud3c9\uba74 \uc704\uc758 \ud55c \uc810\uc73c\ub85c\ubd80\ud130 \uc77c\uc815\ud55c \uac70\ub9ac\uc5d0 \uc788\ub294 \uc810\ub4e4\uc758 \uc9d1\ud569\uc785\ub2c8\ub2e4. \uc774\ub54c \'\uc77c\uc815\ud55c \uac70\ub9ac\'\ub97c \uc6b0\ub9ac\ub294 \'\ubc18\uc9c0\ub984(radius)\'\uc774\ub77c\uace0 \ubd80\ub974\uba70, \ubcf4\ud1b5 \uc54c\ud30c\ubcb3 $r$\ub85c \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uc6d0\uc758 \uc911\uc2ec\uc744 $(a, b)$\ub77c\uace0 \ud560 \ub54c, \uc6d0 \uc704\uc758 \uc784\uc758\uc758 \uc810\uc744 $(x, y)$\ub77c\uace0 \ud558\uba74 \ub450 \uc810 \uc0ac\uc774\uc758 \uac70\ub9ac \uacf5\uc2dd\uc5d0 \uc758\ud574 \uc6d0\uc758 \ubc29\uc815\uc2dd\uc740 $$(x - a)^2 + (y - b)^2 = r^2$$\uacfc \uac19\uc774 \ud45c\ud604\ub429\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc6b0\ubcc0\uc758 $r^2$\uc740 \ubc18\uc9c0\ub984\uc758 \uc81c\uacf1\uc744 \uc758\ubbf8\ud558\uba70, \ubc18\uc9c0\ub984 $r$\uc740 \ud56d\uc0c1 \uc591\uc218($r > 0$)\uc5ec\uc57c \ud55c\ub2e4\ub294 \uc810\uc774 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4.",   "\ubc18\uc9c0\ub984\uc740 \uc6d0\uc758 \ud06c\uae30\ub97c \uacb0\uc815\ud558\ub294 \ud575\uc2ec \uc694\uc18c\uc785\ub2c8\ub2e4. \uc6d0\uc758 \ubc29\uc815\uc2dd\uc774 \ud45c\uc900\ud615\uc778 $(x - a)^2 + (y - b)^2 = r^2$ \uaf34\ub85c \uc8fc\uc5b4\uc84c\uc744 \ub54c, \uc6b0\ubcc0\uc758 \uac12\uc744 \ud655\uc778\ud558\uc5ec \uc81c\uacf1\uadfc\uc744 \ucde8\ud558\uba74 \ubc18\uc9c0\ub984\uc744 \ubc14\ub85c \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub9cc\uc57d \ubc29\uc815\uc2dd\uc774 \uc77c\ubc18\ud615\uc778 $x^2 + y^2 + Ax + By + C = 0$\uc73c\ub85c \uc8fc\uc5b4\uc9c4\ub2e4\uba74, \uc644\uc804\uc81c\uacf1\uc2dd\uc73c\ub85c \ubcc0\ud615\ud558\uc5ec $$(x + \\frac{A}{2})^2 + (y + \\frac{B}{2})^2 = \\frac{A^2 + B^2 - 4C}{4}$$\uc758 \ud615\ud0dc\ub85c \ub9cc\ub4e0 \ub4a4, \uc6b0\ubcc0\uc758 \uac12\uc5d0 \ub8e8\ud2b8\ub97c \uc50c\uc6cc \ubc18\uc9c0\ub984\uc744 \ucc3e\uc544\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4.",   "\uc608\uc81c 1: \uc6d0\uc758 \ubc29\uc815\uc2dd $(x - 3)^2 + (y + 2)^2 = 16$\uc774 \uc8fc\uc5b4\uc84c\uc744 \ub54c, \uc774 \uc6d0\uc758 \ubc18\uc9c0\ub984\uc744 \uad6c\ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uc8fc\uc5b4\uc9c4 \uc2dd\uc744 \ud45c\uc900\ud615\uc778 $(x - a)^2 + (y - b)^2 = r^2$\uacfc \ube44\uad50\ud569\ub2c8\ub2e4. \uc2dd\uc5d0\uc11c $r^2 = 16$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\uc9c0\ub984 $r$\uc740 \uae38\uc774\ub97c \ub098\ud0c0\ub0b4\ubbc0\ub85c \ud56d\uc0c1 \uc591\uc218\uc5ec\uc57c \ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c $r = \\sqrt{16} = 4$\uac00 \ub429\ub2c8\ub2e4. \uc989, \uc774 \uc6d0\uc758 \ubc18\uc9c0\ub984\uc740 4\uc785\ub2c8\ub2e4.",   "\uc608\uc81c 2: \ubc29\uc815\uc2dd $x^2 + y^2 - 4x + 6y - 3 = 0$\uc774 \ub098\ud0c0\ub0b4\ub294 \uc6d0\uc758 \ubc18\uc9c0\ub984\uc744 \uad6c\ud558\ub294 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. \uba3c\uc800 $x$\ud56d\uacfc $y$\ud56d\uc744 \uac01\uac01 \ubb36\uc5b4 \uc644\uc804\uc81c\uacf1\uc2dd\uc73c\ub85c \ub9cc\ub4ed\ub2c8\ub2e4. $(x^2 - 4x + 4) + (y^2 + 6y + 9) = 3 + 4 + 9$\uac00 \ub418\uc5b4, \uc815\ub9ac\ud558\uba74 $$(x - 2)^2 + (y + 3)^2 = 16$$\uc774 \ub429\ub2c8\ub2e4. \uc774 \uc2dd\uc5d0\uc11c $r^2 = 16$\uc774\ubbc0\ub85c, \ubc18\uc9c0\ub984 $r$\uc740 $\\sqrt{16} = 4$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.",   "\uc774\ucc98\ub7fc \ubc18\uc9c0\ub984\uc740 \uc6d0\uc758 \uc911\uc2ec\uc5d0\uc11c \uc6d0 \uc704\uc758 \uc784\uc758\uc758 \uc810\uae4c\uc9c0 \uc774\ub974\ub294 \uac70\ub9ac\ub97c \uc758\ubbf8\ud558\uba70, \uc6d0\uc758 \ubc29\uc815\uc2dd\uc5d0\uc11c \uac00\uc7a5 \uc911\uc694\ud55c \uc815\ubcf4 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. \ubb38\uc81c\ub97c \ud480 \ub54c \ud56d\uc0c1 \uc6b0\ubcc0\uc774 \ubc18\uc9c0\ub984\uc758 \'\uc81c\uacf1\' \uac12\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744 \uae30\uc5b5\ud558\uc138\uc694. \ubc18\uc9c0\ub984\uc774 \uc8fc\uc5b4\uc9c0\uba74 \uc6d0\uc758 \ub458\ub808($2\\pi r$)\ub098 \ub113\uc774($\\pi r^2$)\ub3c4 \uc27d\uac8c \uad6c\ud560 \uc218 \uc788\uc73c\ubbc0\ub85c, \ubc29\uc815\uc2dd\uc5d0\uc11c $r$\uc758 \uac12\uc744 \uc815\ud655\ud788 \ucd94\ucd9c\ud558\ub294 \uc5f0\uc2b5\uc744 \ucda9\ubd84\ud788 \ud574\ub450\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4." ]'],ai0),"\ubc18\uc9c0\ub984",B.p)],ai2),"\ubc18\uc9c0\ub984",B.p)],ai3),s3,s3,s3,"concept_\ubc18\uc9c0\ub984",0,"","\uacf5\ud1b5\uc218\ud5592 > \uc6d0\uc758\ubc29\uc815\uc2dd > \uc6d0\uc758\ud45c\uc900\ud615 > \ubc18\uc9c0\ub984",c9,"\ubc18\uc9c0\ub984",s3)
d0=A.a(["\uacf5\ud1b5\uc218\ud5591","\uc774\ucc28\ubc29\uc815\uc2dd","\uc774\ucc28\ubc29\uc815\uc2dd\uc758\ud480\uc774","\uc778\uc218\ubd84\ud574\ubc95"],ai0)
d0=A.au(s2,A.a([A.at(A.a(["\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ubc29\uc815\uc2dd > \uc774\ucc28\ubc29\uc815\uc2dd\uc758\ud480\uc774 > \uc778\uc218\ubd84\ud574\ubc95 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.av(s3,B.q,A.a(["\uc774\ucc28\ubc29\uc815\uc2dd\uc758 \uc778\uc218\ubd84\ud574\ubc95\uc740 \uc774\ucc28\ubc29\uc815\uc2dd $ax^2 + bx + c = 0$ ($a \\neq 0$)\uc758 \uc88c\ubcc0\uc744 \ub450 \uc77c\ucc28\uc2dd\uc758 \uacf1\uc73c\ub85c \ub098\ud0c0\ub0b4\uc5b4 \ud574\ub97c \uad6c\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4. \uc774\ub294 '\ub450 \uc218\uc758 \uacf1\uc774 0\uc774\uba74, \uc801\uc5b4\ub3c4 \ud558\ub098\ub294 0\uc774\ub2e4'\ub77c\ub294 \uc131\uc9c8\uc778 $AB = 0 \\iff A = 0$ \ub610\ub294 $B = 0$\uc744 \uc774\uc6a9\ud569\ub2c8\ub2e4. \uc989, \uc774\ucc28\uc2dd\uc744 $(px + q)(rx + s) = 0$\uc758 \uaf34\ub85c \ubcc0\ud615\ud558\uba74, $px + q = 0$ \ub610\ub294 $rx + s = 0$\uc744 \ub9cc\uc871\ud558\ub294 $x$ \uac12\uc744 \uac01\uac01 \ucc3e\uc544\ub0b4\uc5b4 \ubc29\uc815\uc2dd\uc758 \ud574\ub97c \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc778\uc218\ubd84\ud574\ub97c \ud558\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \uc2dd\uc758 \ud615\ud0dc\ub97c \uad00\ucc30\ud574\uc57c \ud569\ub2c8\ub2e4. \uac00\uc7a5 \uba3c\uc800 \uacf5\ud1b5\uc778\uc218\ub97c \ubb36\uc5b4\ub0b4\uace0, \uc774\ud6c4\uc5d0\ub294 \uacf1\uc148 \uacf5\uc2dd\uc758 \uc5ed\uacfc\uc815\uc744 \uc801\uc6a9\ud569\ub2c8\ub2e4. \ud2b9\ud788 $x^2 + (a+b)x + ab = (x+a)(x+b)$\uc640 \uac19\uc740 \ud615\ud0dc\ub098, \uc644\uc804\uc81c\uacf1\uc2dd $x^2 + 2ax + a^2 = (x+a)^2$\uc744 \ud65c\uc6a9\ud558\ub294 \uac83\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4. \ub9cc\uc57d $x^2$\uc758 \uacc4\uc218\uac00 1\uc774 \uc544\ub2c8\ub77c\uba74, \ub300\uac01\uc120 \uacf1\uc148\ubc95\uc744 \uc0ac\uc6a9\ud558\uc5ec \uacc4\uc218\ub97c \ub9de\ucd94\ub294 \uc5f0\uc2b5\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.","\uc608\ub97c \ub4e4\uc5b4, \uc774\ucc28\ubc29\uc815\uc2dd $x^2 - 5x + 6 = 0$\uc744 \ud480\uc5b4\ubd05\uc2dc\ub2e4. \uba3c\uc800 \uc88c\ubcc0\uc758 \uc774\ucc28\uc2dd $x^2 - 5x + 6$\uc744 \uc778\uc218\ubd84\ud574\ud574\uc57c \ud569\ub2c8\ub2e4. \uacf1\ud574\uc11c $6$\uc774 \ub418\uace0 \ub354\ud574\uc11c $-5$\uac00 \ub418\ub294 \ub450 \uc815\uc218\ub97c \ucc3e\uc73c\uba74 $-2$\uc640 $-3$\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2dd\uc740 $(x - 2)(x - 3) = 0$\uc73c\ub85c \uc778\uc218\ubd84\ud574\ub429\ub2c8\ub2e4. \uc774\uc81c \ub450 \uc77c\ucc28\uc2dd\uc758 \uacf1\uc774 0\uc774 \ub418\ub294 \uc870\uac74\uc744 \uc801\uc6a9\ud569\ub2c8\ub2e4.","\uc704 \uc2dd\uc5d0\uc11c $(x - 2)(x - 3) = 0$\uc774 \uc131\ub9bd\ud558\ub824\uba74 $x - 2 = 0$ \ub610\ub294 $x - 3 = 0$\uc774\uc5b4\uc57c \ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c $x = 2$ \ub610\ub294 $x = 3$\uc774 \uc774 \uc774\ucc28\ubc29\uc815\uc2dd\uc758 \ud574\uac00 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc778\uc218\ubd84\ud574\ubc95\uc740 \uc774\ucc28\ubc29\uc815\uc2dd\uc744 \uac00\uc7a5 \ube60\ub974\uace0 \ud6a8\uc728\uc801\uc73c\ub85c \ud574\uacb0\ud560 \uc218 \uc788\ub294 \ubc29\ubc95 \uc911 \ud558\ub098\uc774\ubbc0\ub85c, \ub2e4\uc591\ud55c \ub2e4\ud56d\uc2dd\uc758 \uc778\uc218\ubd84\ud574 \ud615\ud0dc\ub97c \uc775\ud600\ub450\ub294 \uac83\uc774 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc870\uae08 \ub354 \ubcf5\uc7a1\ud55c \uc608\uc81c\ub85c $2x^2 + 7x + 3 = 0$\uc744 \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. \uc774 \uc2dd\uc740 $x^2$\uc758 \uacc4\uc218\uac00 $2$\uc774\ubbc0\ub85c \ub300\uac01\uc120 \uacf1\uc148\ubc95\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uacf1\ud574\uc11c $2$\uac00 \ub418\ub294 \uc218 $1, 2$\uc640 \uacf1\ud574\uc11c $3$\uc774 \ub418\ub294 \uc218 $1, 3$\uc744 \ubc30\uc5f4\ud558\uc5ec \ud569\uc774 $7$\uc774 \ub418\ub3c4\ub85d \uc870\ud569\ud569\ub2c8\ub2e4. $(1 \\times 1) + (2 \\times 3) = 7$\uc774 \ub418\ubbc0\ub85c, \uc2dd\uc740 $(x + 3)(2x + 1) = 0$\uc73c\ub85c \uc778\uc218\ubd84\ud574\ub429\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc778\uc218\ubd84\ud574\ub41c \uc2dd $(x + 3)(2x + 1) = 0$\uc5d0\uc11c \uac01 \uc778\uc218\uac00 0\uc774 \ub418\ub294 \uac12\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. $x + 3 = 0$\uc5d0\uc11c $x = -3$\uc744 \uc5bb\uace0, $2x + 1 = 0$\uc5d0\uc11c $2x = -1$, \uc989 $x = -\\frac{1}{2}$\uc744 \uc5bb\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc8fc\uc5b4\uc9c4 \uc774\ucc28\ubc29\uc815\uc2dd\uc758 \ucd5c\uc885 \ud574\ub294 $x = -3$ \ub610\ub294 $x = -\\frac{1}{2}$\uc785\ub2c8\ub2e4."],ai0),v9,B.p)],ai2),v9,B.p)],ai3),s3,s3,s3,"concept_\uc778\uc218\ubd84\ud574\ubc95",0,"","\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ubc29\uc815\uc2dd > \uc774\ucc28\ubc29\uc815\uc2dd\uc758\ud480\uc774 > \uc778\uc218\ubd84\ud574\ubc95",d0,v9,s3)
